   return {
     id: pokemon.id,
     name: titleName(pokemon.name),
     speciesId: resourceId(pokemon.species),
     types: pokemon.types.map(({ type }) => type.name),
     abilities: pokemon.abilities.map(({ ability }) => titleName(ability.name)),
     height: pokemon.height,
